import re
import xml.etree.ElementTree as et


class PdmlRrcParser(object):
    def __init__(self):
        self.name_regex = re.compile(r'([01.]+ [01.]+ )?([a-zA-Z0-9_-]+)(: (\S+))?')

    def parse(self, pdmlstring):
        """
        Parses RRC messages stored in PDML format in a release-independent way. The content of data structures is
        based solely on the information provided by the input PDML without relying on external tools.
        :param pdmlstring: A PDML string.
        :return: Data structure containing parsed RRC messages.
        """
        pdml = et.fromstring(pdmlstring)
        messages = []
        for packet in pdml.findall('packet'):
            rrc_packet = packet.find('./proto[@name="lte_rrc"]')
            if rrc_packet is not None:
                messages.append(self._process_rrc_structure(rrc_packet))
        return messages

    def _process_rrc_field(self, field):
        subelements = list(field)
        if len(subelements) == 0:
            return self._process_rrc_value(field)
        elif self._is_field_extended(field):
            return self._process_rrc_field(subelements[0])
        else:
            return self._process_rrc_structure(field)

    def _is_field_extended(self, field):
        if list(field).__len__() == 1:
            subelement = list(field)[0]
            return subelement.get('name').startswith('lte-rrc') \
                and self._extract_printable_name(subelement)[0].isupper()
        return False

    def _process_rrc_structure(self, struct):
        data = dict()
        field_iterator = list(struct).__iter__()
        try:
            while True:
                self._process_rrc_element(data, field_iterator)
        except StopIteration:
            pass
        if data.__len__() == 0 and struct.get('value'):
            return self._process_rrc_value(struct)
        return data

    def _process_rrc_element(self, data, iterator):
        field = next(iterator)
        if field.get('name').startswith('lte-rrc'):
            data[self._extract_printable_name(field)] = self._process_rrc_field(field)
        elif field.get('name') == 'per.enum_index':
            field = next(iterator)
            data[self._extract_printable_name(field)] = self._process_rrc_enum(field)
        elif field.get('name') == 'per.sequence_of_length':
            field = next(iterator)
            data[self._extract_printable_name(field)] = self._process_rrc_list(field)

    def _match_showname(self, field):
        return self.name_regex.match(field.get('showname'))

    def _extract_printable_name(self, field):
        return self._match_showname(field).group(2)

    def _process_rrc_enum(self, field):
        return self._match_showname(field).group(4)

    def _process_rrc_list(self, field):
        data = list()
        for elem in field:
            data.append(self._process_rrc_field(elem))
        return data

    def _process_rrc_value(self, field):
        matched_name = self._match_showname(field)
        if matched_name.group(1):
            return matched_name.group(4) == 'True'
        elif matched_name.group(4) == 'NULL':
            return None
        else:
            try:
                return int(field.get('show'))
            except ValueError:
                return self._covert_field_value_from_hex(field)
            except TypeError:
                return None

    def _covert_field_value_from_hex(self, field):
        try:
            return int(field.get('value'), 16)
        except TypeError:
            return None
